import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_conv3d_cuda = load_inline(
    name="conv3d_single_kernel_ext",
    cpp_sources=r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

torch::Tensor conv3d_cuda_forward(
    const torch::Tensor& input,
    const torch::Tensor& weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &conv3d_cuda_forward, "Single-kernel CUDA Conv3d forward");
}
""",
    cuda_sources=r"""
#include <torch/extension.h>
#include <ATen/AccumulateType.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
template <typename scalar_t, typename acc_t>
__global__ void conv3d_forward_kernel_tiled(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int64_t N,
    int64_t Cin,
    int64_t Din,
    int64_t Hin,
    int64_t Win,
    int64_t Cout,
    int64_t Dout,
    int64_t Hout,
    int64_t Wout,
    int64_t K,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups,
    bool has_bias,
    int64_t tile_h,
    int64_t tile_w,
    int64_t tile_d) {
    const int64_t ow = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const int64_t oh = static_cast<int64_t>(blockIdx.y) * blockDim.y + threadIdx.y;
    const int64_t packed = static_cast<int64_t>(blockIdx.z);
    const int64_t depth_tiles = (Dout + blockDim.z - 1) / blockDim.z;
    const int64_t od_tile = packed % depth_tiles;
    const int64_t tmp = packed / depth_tiles;
    const int64_t oc = tmp % Cout;
    const int64_t n = tmp / Cout;
    const int64_t od0 = od_tile * blockDim.z;
    const int64_t od = od0 + threadIdx.z;
    extern __shared__ unsigned char shared_raw[];
    scalar_t* shared_input = reinterpret_cast<scalar_t*>(shared_raw);
    const bool valid_output = n < N && oc < Cout && od < Dout && oh < Hout && ow < Wout;
    const int64_t cin_per_group = Cin / groups;
    const int64_t cout_per_group = Cout / groups;
    const int64_t group = oc / cout_per_group;
    const int64_t cin_start = group * cin_per_group;
    const int64_t oh0 = static_cast<int64_t>(blockIdx.y) * blockDim.y;
    const int64_t ow0 = static_cast<int64_t>(blockIdx.x) * blockDim.x;
    const int64_t input_d0 = od0 * stride - padding;
    const int64_t input_h0 = oh0 * stride - padding;
    const int64_t input_w0 = ow0 * stride - padding;
    const int64_t tile_elems = tile_d * tile_h * tile_w;
    const int64_t tid =
        (static_cast<int64_t>(threadIdx.z) * blockDim.y + threadIdx.y) * blockDim.x +
        threadIdx.x;
    const int64_t tcount =
        static_cast<int64_t>(blockDim.x) * blockDim.y * blockDim.z;
    acc_t sum = acc_t(0);
    for (int64_t ic_local = 0; ic_local < cin_per_group; ++ic_local) {
        const int64_t ic = cin_start + ic_local;
        for (int64_t linear = tid; linear < tile_elems; linear += tcount) {
            const int64_t tw = linear % tile_w;
            const int64_t temp = linear / tile_w;
            const int64_t th = temp % tile_h;
            const int64_t td = temp / tile_h;
            const int64_t id = input_d0 + td;
            const int64_t ih = input_h0 + th;
            const int64_t iw = input_w0 + tw;
            scalar_t value = scalar_t(0);
            if (id >= 0 && id < Din && ih >= 0 && ih < Hin && iw >= 0 && iw < Win) {
                const int64_t input_idx =
                    (((n * Cin + ic) * Din + id) * Hin + ih) * Win + iw;
                value = input[input_idx];
            }
            shared_input[linear] = value;
        }
        __syncthreads();
        if (valid_output) {
            const int64_t local_oh = threadIdx.y;
            const int64_t local_ow = threadIdx.x;
            const int64_t local_od = threadIdx.z;
            for (int64_t kd = 0; kd < K; ++kd) {
                for (int64_t kh = 0; kh < K; ++kh) {
                    for (int64_t kw = 0; kw < K; ++kw) {
                        const int64_t shared_d = local_od * stride + kd * dilation;
                        const int64_t shared_h = local_oh * stride + kh * dilation;
                        const int64_t shared_w = local_ow * stride + kw * dilation;
                        const int64_t shared_idx =
                            (shared_d * tile_h + shared_h) * tile_w + shared_w;
                        const int64_t weight_idx =
                            ((((oc * cin_per_group + ic_local) * K + kd) * K + kh) * K + kw);
                        sum += static_cast<acc_t>(shared_input[shared_idx]) *
                               static_cast<acc_t>(weight[weight_idx]);
                    }
                }
            }
        }
        __syncthreads();
    }
    if (valid_output) {
        if (has_bias) {
            sum += static_cast<acc_t>(bias[oc]);
        }
        const int64_t output_idx =
            (((n * Cout + oc) * Dout + od) * Hout + oh) * Wout + ow;
        output[output_idx] = static_cast<scalar_t>(sum);
    }
}
torch::Tensor conv3d_cuda_forward(
    const torch::Tensor& input,
    const torch::Tensor& weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 5, "input must have shape [N, C, D, H, W]");
    TORCH_CHECK(weight.dim() == 5, "weight must have shape [Cout, Cin/groups, K, K, K]");
    TORCH_CHECK(stride > 0, "stride must be positive");
    TORCH_CHECK(dilation > 0, "dilation must be positive");
    TORCH_CHECK(groups > 0, "groups must be positive");
    TORCH_CHECK(input.scalar_type() == weight.scalar_type(),
                "input and weight must have the same dtype");
    const auto N = input.size(0);
    const auto Cin = input.size(1);
    const auto Din = input.size(2);
    const auto Hin = input.size(3);
    const auto Win = input.size(4);
    const auto Cout = weight.size(0);
    const auto cin_per_group = weight.size(1);
    const auto K = weight.size(2);
    TORCH_CHECK(weight.size(3) == K && weight.size(4) == K,
                "only cubic kernels are supported");
    TORCH_CHECK(Cin % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(Cout % groups == 0, "output channels must be divisible by groups");
    TORCH_CHECK(cin_per_group == Cin / groups,
                "weight channel dimension does not match input/groups");
    bool has_bias = bias.has_value() && bias->defined();
    torch::Tensor bias_c;
    if (has_bias) {
        TORCH_CHECK(bias->is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias->scalar_type() == input.scalar_type(),
                    "bias must have the same dtype as input");
        TORCH_CHECK(bias->numel() == Cout, "bias has incorrect size");
        bias_c = bias->contiguous();
    }
    const auto effective_k = dilation * (K - 1) + 1;
    const auto Dout = (Din + 2 * padding - effective_k) / stride + 1;
    const auto Hout = (Hin + 2 * padding - effective_k) / stride + 1;
    const auto Wout = (Win + 2 * padding - effective_k) / stride + 1;
    TORCH_CHECK(Dout >= 0 && Hout >= 0 && Wout >= 0,
                "calculated output size is invalid");
    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    auto output = torch::empty({N, Cout, Dout, Hout, Wout}, input.options());
    c10::cuda::CUDAGuard device_guard(input.device());
    cudaStream_t stream = at::cuda::getCurrentCUDAStream(input.device().index());
    const dim3 block(8, 4, 2);
    const int64_t depth_tiles = (Dout + block.z - 1) / block.z;
    const dim3 grid(
        static_cast<unsigned int>((Wout + block.x - 1) / block.x),
        static_cast<unsigned int>((Hout + block.y - 1) / block.y),
        static_cast<unsigned int>(N * Cout * depth_tiles));
    const int64_t tile_h = (block.y - 1) * stride + effective_k;
    const int64_t tile_w = (block.x - 1) * stride + effective_k;
    const int64_t tile_d = (block.z - 1) * stride + effective_k;
    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        input.scalar_type(),
        "conv3d_forward_cuda_tiled",
        [&] {
            using acc_t = at::acc_type<scalar_t, true>;
            const scalar_t* bias_data = has_bias ? bias_c.data_ptr<scalar_t>() : nullptr;
            const size_t shared_bytes = static_cast<size_t>(tile_d) *
                static_cast<size_t>(tile_h) * static_cast<size_t>(tile_w) * sizeof(scalar_t);
            conv3d_forward_kernel_tiled<scalar_t, acc_t><<<grid, block, shared_bytes, stream>>>(
                input_c.data_ptr<scalar_t>(),
                weight_c.data_ptr<scalar_t>(),
                bias_data,
                output.data_ptr<scalar_t>(),
                N, Cin, Din, Hin, Win,
                Cout, Dout, Hout, Wout,
                K, stride, padding, dilation, groups,
                has_bias, tile_h, tile_w, tile_d);
        });
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
""",
    functions=None,
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv3d = nn.Conv3d(
            in_channels,
            out_channels,
            (kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _conv3d_cuda.forward(
            x,
            self.conv3d.weight,
            self.conv3d.bias,
            self.conv3d.stride[0],
            self.conv3d.padding[0],
            self.conv3d.dilation[0],
            self.conv3d.groups,
        )

